// Convierte cada fila de la tabla del BCRP en un registro: fecha, compra y venta.
const cfg = $('Armar URL de consulta').first().json;
const d = $input.first().json;
const MESES = { Ene: 1, Feb: 2, Mar: 3, Abr: 4, May: 5, Jun: 6, Jul: 7, Ago: 8, Set: 9, Sep: 9, Oct: 10, Nov: 11, Dic: 12 };
const texto = (h) => String(h || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const ahora = $now.setZone('America/Lima').toFormat('yyyy-MM-dd HH:mm:ss');

const registros = [];
const sinDato = [];
for (const fila of (Array.isArray(d.filas) ? d.filas : [])) {
  const celdas = [...String(fila).matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map((m) => texto(m[1]));
  if (celdas.length < 3) continue;                       // encabezados u otras filas
  const m = celdas[0].match(/^(\d{2})\.?([A-Za-zé]{3})\.?(\d{2})$/);
  if (!m || !MESES[m[2]]) continue;
  const fecha = `20${m[3]}-${String(MESES[m[2]]).padStart(2, '0')}-${m[1]}`;
  const num = (v) => (/^-?\d+(\.\d+)?$/.test(v) ? Number(v) : null);
  const compra = num(celdas[1]), venta = num(celdas[2]);
  if (compra === null || venta === null) { sinDato.push(`${celdas[0]} (${celdas[1]} / ${celdas[2]})`); continue; }
  registros.push({ fecha, fecha_bcrp: celdas[0], compra, venta });
}
registros.sort((a, b) => a.fecha.localeCompare(b.fecha));

return [{ json: {
  titulo_pagina: d.titulo || '',
  encabezados: d.encabezados || [],
  url_consulta: cfg.url_consulta,
  url_api: cfg.url_api,
  fecha_consulta: ahora,
  total_registros: registros.length,
  fechas_sin_dato: sinDato,
  registros,
} }];

// Una fila por fecha con los encabezados del Excel y la fuente de consulta.
const d = $input.first().json;
const cfg = $('Configuración').first().json;
return d.registros.map((r, i) => ({ json: {
  'N°': i + 1,
  'Fecha': DateTime.fromISO(r.fecha).toFormat('dd/MM/yyyy'),
  'Fecha según BCRP': r.fecha_bcrp,
  'Compra (S/ por US$)': r.compra,
  'Venta (S/ por US$)': r.venta,
  'Serie compra': cfg.serie_compra,
  'Serie venta': cfg.serie_venta,
  'Fuente de consulta (URL)': d.url_consulta,
  'Fecha y hora de consulta': d.fecha_consulta,
} }));

// Resumen medido de la ejecución (no son estimaciones).
const cfg = $('Configuración').first().json;
const org = $('Organizar registros').first().json;
const filas = $('Columnas del Excel').all().map((i) => i.json);
const inicio = DateTime.fromISO(cfg.inicio);
const fin = $now;
return [{ json: {
  'Fechas con dato': filas.length,
  'Rango consultado': `${cfg.fecha_inicio} a ${cfg.fecha_fin}`,
  'Primera fecha': filas[0]['Fecha'],
  'Última fecha': filas[filas.length - 1]['Fecha'],
  'Fechas sin dato (n.d.)': org.fechas_sin_dato.length ? org.fechas_sin_dato.join(', ') : 'Ninguna',
  'Archivo Excel': `${cfg.carpeta_salida.replace(/[\/\\]+$/, '')}/${$('Generar Excel').first().binary.data.fileName}`,
  'Duración (segundos)': Math.round(fin.diff(inicio, 'seconds').seconds * 10) / 10,
} }];

// Compara cada fecha del Excel con la respuesta de la API oficial del BCRP.
const MESES = { Ene: 1, Feb: 2, Mar: 3, Abr: 4, May: 5, Jun: 6, Jul: 7, Ago: 8, Set: 9, Sep: 9, Oct: 10, Nov: 11, Dic: 12 };
const api = $input.first().json;
const periodos = Array.isArray(api.periods) ? api.periods : [];
const porFecha = {};
for (const p of periodos) {
  const m = String(p.name).match(/^(\d{2})\.?([A-Za-zé]{3})\.?(\d{2})$/);
  if (!m || !MESES[m[2]]) continue;
  porFecha[`20${m[3]}-${String(MESES[m[2]]).padStart(2, '0')}-${m[1]}`] = p.values || [];
}
const ahora = $now.setZone('America/Lima').toFormat('yyyy-MM-dd HH:mm:ss');
const regs = $('Organizar registros').first().json.registros;
return regs.map((r, i) => {
  const v = porFecha[r.fecha];
  // La API entrega más decimales; el BCRP publica 3 decimales, así que se redondea a 3 para comparar.
  const r3 = (x) => Math.round(Number(x) * 1000) / 1000;
  const cApi = v && v[0] !== 'n.d.' ? r3(v[0]) : null, vApi = v && v[1] !== 'n.d.' ? r3(v[1]) : null;
  const ok = cApi !== null && vApi !== null && cApi === r3(r.compra) && vApi === r3(r.venta);
  return { json: {
    'N°': i + 1,
    'Fecha': DateTime.fromISO(r.fecha).toFormat('dd/MM/yyyy'),
    'Compra en Excel': r.compra,
    'Compra en API BCRP (3 decimales)': cApi !== null ? cApi : '(sin dato en la API)',
    'Venta en Excel': r.venta,
    'Venta en API BCRP (3 decimales)': vApi !== null ? vApi : '(sin dato en la API)',
    'Resultado': ok ? 'COINCIDE' : 'NO COINCIDE',
    'Fuente de verificación (API)': $('Organizar registros').first().json.url_api,
    'Fecha y hora de verificación': ahora,
  } };
});

// Respuesta que recibe el asistente: solo datos obtenidos del BCRP, sin estimaciones.
const cfg = $('Configuración').first().json;
const res = $('Resumen de la ejecución').first().json;
const filas = $('Columnas del Excel').all().map((i) => i.json);
const ver = $('Comparar con el Excel').all().map((i) => i.json);
const archivo = $('Generar Excel').first().binary.data.fileName;
const archivoVer = $('Generar Excel de verificación').first().binary.data.fileName;
const coinciden = ver.filter((v) => v['Resultado'] === 'COINCIDE').length;
const enlace = (n) => 'https://sysdespacho-bot-rpa.onrender.com/webhook/sysdespacho/excel?archivo=' + encodeURIComponent(n);
return [{ json: {
  ok: true,
  registros: filas.length,
  rango_consultado: `${cfg.fecha_inicio} a ${cfg.fecha_fin}`,
  primera_fecha: res['Primera fecha'],
  ultima_fecha: res['Última fecha'],
  fechas_sin_dato: res['Fechas sin dato (n.d.)'],
  excel_generado: true,
  archivo_excel: archivo,
  enlace_descarga_excel: enlace(archivo),
  verificacion_api: `${coinciden} de ${ver.length} fechas coinciden con la API oficial del BCRP`,
  enlace_descarga_verificacion: enlace(archivoVer),
  tipo_cambio: filas.map((f) => ({ fecha: f['Fecha'], compra: f['Compra (S/ por US$)'], venta: f['Venta (S/ por US$)'] })),
  fuente: filas[0]['Fuente de consulta (URL)'],
  duracion_segundos: res['Duración (segundos)'],
} }];
